		.FootLeftRotation{FQuat{FeetState.Left.FinalRotation}},
		.FootRightLocation{FVector{FeetState.Right.FinalLocation}},
		.FootRightRotation{FQuat{FeetState.Right.FinalRotation}},
	};
}

	const auto FootLeftTargetTransform{
